import {UK_PATH} from './uk-outline.js?v=20261023-geography01';
export const views2={
 'coast-deposition':[['beach','Beach'],['spit','Spit'],['bar','Bar'],['mouth','Open estuary']],
 'coast-people':[['town','Urban growth'],['farm','Farming'],['port','Industry & port'],['flood','Flooding']],
 'coast-hard':[['wall','Sea wall'],['groyne','Groyne'],['armour','Rip rap'],['down','Downdrift effects']],
 'coast-soft':[['nourish','Nourishment'],['repeat','Sediment loss'],['realign','Realignment'],['judge','Compare priorities']],
 swanage:[['photo','Real photograph'],['location','Locate Swanage'],['geology','Rock contrasts'],['management','Managed bay']]
};
export const requirements2=Object.fromEntries(Object.entries(views2).map(([k,v])=>[k,v.map(x=>x[0])]));
const tx=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const ar=(a,b,c,d)=>`<path d="M${a} ${b}L${c} ${d}" stroke="#ef9c88" stroke-width="3" marker-end="url(#c2arrow)" fill="none"/>`;
const houses=(x,y)=>Array.from({length:4},(_,i)=>`<path d="M${x+i*35} ${y}l12-12 12 12v22h-24Z" fill="#f1dfce" stroke="#c4aa93"/>`).join('');
const water=(t,y=235)=>`<path d="M20 ${y}Q${70+t*25} ${y-9} 150 ${y}T280 ${y}T420 ${y}V330H20Z" fill="#50879d"/><path d="M20 ${y}Q${70+t*25} ${y-9} 150 ${y}T280 ${y}T420 ${y}" stroke="#c8e5e8" fill="none" stroke-width="3"/>`;
const dots=(t,y=210)=>Array.from({length:6},(_,i)=>`<circle cx="${45+(i*43+t*130)%325}" cy="${y+Math.sin(i+t*5)*7}" r="4" fill="#f1d4b1"/>`).join('');
export function scene2(kind,selection,t=0){if(!views2[kind])return '';t=Math.min(1,Math.max(0,Number(t)||0));const s=views2[kind].some(v=>v[0]===selection)?selection:views2[kind][0][0];let body='',caption='';
 if(kind==='swanage'&&s==='photo')return `<figure style="margin:0"><img role="img" src="./geography/images/old-harry-nilfanion.jpg" width="4288" height="2848" style="width:100%;height:auto;border-radius:10px;display:block" alt="Old Harry Rocks photographed from the sea: pale chalk cliffs, sea openings and a detached rock pillar toward the left."><figcaption class="geo-caption">Old Harry Rocks · 17 October 2013. Photo: <a style="color:inherit" href="https://commons.wikimedia.org/wiki/File:Old_Harry_Rocks_(2535).jpg" target="_blank" rel="noopener">Nilfanion / Wikimedia UK</a> · <a style="color:inherit" href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>. Unchanged. Observe the pale cliffs and detached rock; this single view does not measure a retreat rate.</figcaption></figure>`;
 if(kind==='coast-deposition'){
  body='<rect x="20" y="55" width="400" height="275" fill="#50879d"/><path d="M20 55H125V175L60 210H20Z" fill="#849a89"/>'+tx(30,35,'PLAN VIEW · schematic coast')+ar(65,120,145,205);
  if(s==='beach'){body+=`<path d="M20 195Q80 190 125 155" stroke="#e1c39c" stroke-width="${15+t*18}" fill="none"/>`+dots(t,240)+tx(205,110,'Sediment accumulates');caption='Sediment accumulates on the shore when inputs and deposition exceed removal. Beach width changes; values and shape are not measured.';}
  else if(s==='spit'||s==='mouth'){body+=`<path d="M65 200Q${150+t*90} 210 ${155+t*165} 210q15 0 20-20" stroke="#e1c39c" stroke-width="14" fill="none"/>`+ar(110,250,300,250)+tx(180,110,'Land attached at one end')+tx(140,180,'Sheltered water',12);if(s==='mouth')body+='<path d="M380 60Q350 140 360 280" fill="none" stroke="#b6e1e3" stroke-width="17"/>'+ar(380,90,360,175)+tx(280,50,'River flow',12);caption=s==='spit'?'Longshore supply extends a spit beyond a bend. A curved tip is possible; sheltered fine sediment may support saltmarsh. This compresses many events.':'River or tidal flow can maintain an open channel beyond a spit. Extension and closure depend on currents, water depth and sediment supply.';}
  else{body+='<path d="M300 55H420V230H360L300 170Z" fill="#849a89"/>'+`<path d="M65 205L${65+t*305} 215" stroke="#e1c39c" stroke-width="18"/>`+tx(190,140,'Lagoon',15)+tx(160,285,'Bar across a bay',14);caption='Deposition can join land at both ends across a bay, enclosing a lagoon. This conditional bar model is not the inevitable next stage of every spit.';}
 }
 if(kind==='coast-people'){
  body='<path d="M20 65H420V330H20Z" fill="#8b9d8a"/>';
  if(s==='town'){body+=houses(65,120)+houses(80,190)+`<path d="M${320-t*65} 65H420V330H${320-t*65}Z" fill="#50879d"/>`+tx(30,40,'Exposure increases near a retreating edge')+tx(35,300,'Buildings shown are invented');caption='More development close to a retreating shore can increase assets at risk. This is a conceptual exposure example, not a prediction for a town.';}
  if(s==='farm'){for(let i=0;i<6;i++)body+=`<rect x="${35+i%3*95}" y="${85+Math.floor(i/3)*90}" width="80" height="70" fill="#bcc199" stroke="#e7e0c7"/>`;body+=water(t,285)+ar(90,150,110,265)+ar(280,150,270,265)+tx(30,40,'Land cover and drainage can change');caption='Fields, drainage and vegetation alter land use and water pathways. Coastal loss or salty flooding can affect farming; the diagram does not quantify either.';}
  if(s==='port'){body+=water(t,155)+'<path d="M180 155V245H340" stroke="#c5bbb0" stroke-width="18" fill="none"/>'+houses(230,100)+dots(t,275)+tx(30,40,'Industry reshapes a frontage')+ar(65,210,165,210);caption='Port structures and reclaimed land can reshape a coast and alter sediment pathways. Investigate both local benefits and effects elsewhere with real evidence.';}
  if(s==='flood'){body+=houses(70,160)+'<path d="M35 235H360" stroke="#c5bbb0" stroke-width="10"/>'+water(t,300-t*110)+tx(30,40,'Inundation: water covers land')+tx(35,110,'A road may remain after water drains');caption='Temporary inundation is different from erosion removing land. Flooding can still damage infrastructure, crops and habitats even when the land remains.';}
 }
 if(kind==='coast-hard'){
  if(s==='groyne'||s==='down'){body='<path d="M20 65H420V210H20Z" fill="#bba88d"/>'+water(t,220)+'<path d="M230 160V300" stroke="#e0c7b0" stroke-width="10"/>'+`<path d="M75 215Q150 ${215-t*35} 225 ${215-t*35}" stroke="#efd6ab" stroke-width="18" fill="none"/>`+ar(45,275,205,275)+tx(30,40,'PLAN VIEW · drift right')+tx(70,145,'Updrift accumulation',12)+tx(275,175,s==='down'?'Possible deficit':'Downdrift',12);if(s==='down')body+=`<path d="M240 ${220+t*28}H410" stroke="#94c0cd" stroke-width="5"/>`;caption=s==='groyne'?'The groyne interrupts alongshore transport, trapping material on the left in this example. It does not create new sediment.':'Holding sediment updrift may reduce the supply reaching the next frontage. A sediment budget is needed before claiming the size or timing of an effect.';}
  else{body='<path d="M265 90H420V330H265Z" fill="#9eaa92"/>'+water(t,230)+ar(70,180,260,220);
   if(s==='wall'){body+='<path d="M270 110V285" stroke="#e0cdbb" stroke-width="18"/>'+ar(260,225,160,245)+tx(30,40,'Wall: protection and reflected energy')+tx(285,80,'Land');caption='A sea wall reduces direct attack on the land behind it. Reflected energy and local scour, maintenance and extreme events still need consideration.';}
   else{for(let i=0;i<9;i++)body+=`<path d="M${215+i%3*23} ${195+Math.floor(i/3)*31}l18-8 10 18-19 13-14-9Z" fill="${i%2?'#8b98a2':'#b1b7b7'}" stroke="#d7dfdf"/>`;body+=tx(30,40,'Rip rap: roughness breaks up wave energy');caption='Large irregular blocks dissipate energy around rough surfaces and gaps. Space, access, cost and landscape effects are part of the comparison.';}
  }
 }
 if(kind==='coast-soft'){
  if(s==='nourish'||s==='repeat'){const w=s==='nourish'?10+t*45:55-t*40;body='<path d="M20 65H420V190H20Z" fill="#8b9d8a"/>'+water(t,225)+`<path d="M20 205H420" stroke="#e8cba4" stroke-width="${w}"/>`+dots(t,255)+tx(30,40,s==='nourish'?'Add sediment → larger beach buffer':'Transport can remove added sediment')+tx(35,120,'Beach material is mobile');caption=s==='nourish'?'Adding sediment widens or raises the buffer that absorbs wave energy. This example contains no measured design volume or promised lifetime.':'Nourished sediment can be transported away. Monitoring and repeat recharge may be needed; costs and disturbance can recur.';}
  else if(s==='realign'){body='<path d="M20 65H420V330H20Z" fill="#8e9e87"/><path d="M20 145H420" stroke="#d9d3bf" stroke-width="8" stroke-dasharray="8 6"/><path d="M20 85H420" stroke="#f1ddbd" stroke-width="9"/>'+water(t,290-t*125)+tx(30,40,'Set-back line above · former line dashed')+tx(35,125,'Existing land use changes',12)+tx(35,315,'Selected tidal space / possible habitat',12);caption='A deliberately set-back defence can make room for tidal adjustment and intertidal habitat in a suitable site. Land use, compensation and people’s losses must be considered.';}
  else{body=water(t,280)+'<rect x="30" y="75" width="175" height="155" rx="12" fill="#415b70"/><rect x="225" y="75" width="185" height="155" rx="12" fill="#415b70"/>'+tx(45,105,'Developed frontage',14)+tx(45,145,'Homes · access',13)+tx(45,175,'Cost · maintenance',12)+tx(240,105,'Space to adapt',14)+tx(240,145,'Land use · habitat',13)+tx(240,175,'Relocation · fairness',12)+tx(30,40,'Compare objectives and distribution of effects');caption='Different places and stakeholder priorities can support different approaches. These are decision prompts, not an automatic ranking or a calibrated cost-benefit model.';}
 }
 if(kind==='swanage'){
  if(s==='location'){body=`<path d="${UK_PATH}" fill="#8daba9"/><circle cx="164" cy="260" r="7" fill="#ef9c88"/>`+ar(172,260,310,280)+tx(305,265,'Swanage',13)+tx(30,40,'South coast of England · Dorset')+tx(30,335,'Natural Earth outline · generalised locator',12);caption='Swanage is in south-east Dorset on England’s south coast. Generalised Natural Earth outline and selected marker; use a detailed map to establish precise positions.';}
  if(s==='geology'){body='<rect x="20" y="65" width="400" height="265" fill="#50879d"/><path d="M20 70H240V115H20Z" fill="#dce2d6"/><path d="M20 115H190Q130 180 195 240H20Z" fill="#c4a58a"/><path d="M20 240H250V305H20Z" fill="#9eaaa1"/>'+tx(30,40,'SCHEMATIC PLAN · sea to the east')+tx(35,98,'Chalk: Ballard / Old Harry',12)+tx(35,180,'Wealden sands / clays',12)+tx(35,275,'Purbeck limestones',12)+tx(265,190,'Swanage Bay',13);caption='BGS identifies Chalk at Ballard/Old Harry, weaker Wealden materials around the bay and Purbeck limestones south. This is a broad conceptual arrangement, not a geological-boundary map.';}
  if(s==='management'){body='<path d="M20 65H420V180H20Z" fill="#8d9e8c"/>'+houses(65,120)+water(0,240)+'<path d="M20 190H420" stroke="#e2cfb4" stroke-width="10"/><path d="M20 213H420" stroke="#e6c7a0" stroke-width="24"/>'+[110,230,350].map(x=>`<path d="M${x} 190V280" stroke="#d2b390" stroke-width="7"/>`).join('')+tx(30,40,'Mechanisms at a developed bay')+tx(50,315,'Wall · groynes · periodic nourishment',13);caption='Sources describe these mechanisms around Swanage’s developed frontage. This is not a survey of actual structures, their number, current condition or every neighbouring policy unit.';}
 }
 return `<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${caption.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><defs><marker id="c2arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#ef9c88"/></marker></defs><g fill="#eaf0f1" font-family="sans-serif">${body}</g></svg><p class="geo-caption">${caption}</p>`;
}
